export type Row = { name: string; count: number };

function present(rows: Row[]): Row[] {
  return rows.filter((row) => row.count !== 0);
}

function widestName(rows: Row[]): number {
  return rows.reduce((widest, row) => Math.max(widest, row.name.length), 0);
}

function line(name: string, value: string | number, width: number): string {
  return name.padEnd(width) + "  " + value + "\n";
}

export function renderReport(rows: Row[]): string {
  const kept = present(rows);
  const width = Math.max(widestName(kept), "total".length);
  const total = kept.reduce((sum, row) => sum + row.count, 0);
  return (
    line("name", "count", width) +
    kept.map((row) => line(row.name, row.count, width)).join("") +
    line("total", total, width)
  );
}

