export type Row = { name: string; count: number };

export function renderReport(rows: Row[]): string {
  const kept = [];
  for (const row of rows) {
    if (row.count !== 0) {
      kept.push(row);
    }
  }
  let widest = 0;
  for (const row of kept) {
    if (row.name.length > widest) {
      widest = row.name.length;
    }
  }
  let out = "name" + " ".repeat(Math.max(0, widest - 4)) + "  count\n";
  let total = 0;
  for (const row of kept) {
    out += row.name + " ".repeat(Math.max(0, widest - row.name.length)) + "  " + row.count + "\n";
    total += row.count;
  }
  out += "total" + " ".repeat(Math.max(0, widest - 5)) + "  " + total + "\n";
  return out;
}
